import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { login, isAuthenticated, getUserRole } from '../utils/auth';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import './styles/Login.scss';

function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isAuthenticated()) {
      const role = getUserRole();
      navigate(role === 'editor' ? '/editor' : '/admin');
    }
  }, [navigate]);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (email === 'admin@example.com' && password === 'admin123') {
      login('admin');
      toast.success('Login successful');
      setTimeout(() => navigate('/admin'), 1000);
    } else if (email === 'editor@example.com' && password === 'editor456') {
      login('editor');
      toast.success('Editor logged in');
      setTimeout(() => navigate('/editor'), 1000);
    } else {
      setError('Invalid credentials');
      toast.error('Login failed');
    }
  };

  return (
    <div className="login container">
      <ToastContainer />
      <form className="login__form" onSubmit={handleSubmit}>
        <h2 className="login__title">CMS Login</h2>
        {error && <div className="login__error">{error}</div>}

        <input
          type="email"
          placeholder="Email"
          className="login__input"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />

        <div className="login__password-wrapper">
          <input
            type={showPass ? 'text' : 'password'}
            placeholder="Password"
            className="login__input"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button
            type="button"
            className="login__toggle"
            onClick={() => setShowPass(!showPass)}
          >
            {showPass ? 'Hide' : 'Show'}
          </button>
        </div>

        <button type="submit" className="login__submit">Login</button>
      </form>
    </div>
  );
}

export default Login;
